'QZ_Tray_Printer' => 'QZ Tray (bu bilgisayardaki yazıcı)',
'QZ_Printer_Name_Hint' => 'Yazıcının, QZ Tray\'in çalıştığı bilgisayarda görünen adı. O bilgisayarın varsayılan yazıcısını kullanmak için boş bırakın. Yazıcıları algılamak için ⟳ simgesine tıklayın.',
'QZ_Not_Running' => 'QZ Tray bu bilgisayarda çalışmıyor. qz.io adresinden kurun ve açık tutun; ardından QZ sorduğunda bu web sitesine izin verin.',
'Detect_Printers' => 'Yazıcıları algıla',
'QZ_Download_Cert' => 'Sertifikayı indir (override.crt)',
'QZ_Setup_Title' => 'QZ Tray ile yazdırma nasıl kurulur (bir kez, etiket yazdıran her bilgisayarda)',
'QZ_Step_Install' => '1. Bu bilgisayara QZ Tray kurun — qz.io adresinden ücretsiz indirin, başlatın ve açık bırakın (Windows\'ta sistem tepsisinde, macOS\'ta menü çubuğunda durur).',
'QZ_Step_Connect' => '2. Etiket yazıcınızı USB ile bağlayın ve işletim sisteminde kurulu olduğunu kontrol edin (Windows: Ayarlar > Yazıcılar ve tarayıcılar — macOS: Sistem Ayarları > Yazıcılar ve Tarayıcılar).',
'QZ_Step_Detect' => '3. Bu bilgisayardaki yazıcıları algılamak için yukarıdaki "Yazıcı adı" alanının yanındaki ⟳ düğmesine tıklayın, ardından etiket yazıcınızı seçin. Bilgisayarın varsayılan yazıcısını kullanmak için alanı boş bırakın.',
'QZ_Step_Cert' => '4. İzin açılır penceresi olmadan yazdırmak için aşağıdaki sertifikayı indirin ve override.crt adıyla QZ Tray kurulum klasörüne kopyalayın (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Ardından QZ Tray\'i kapatıp yeniden başlatın.',
'QZ_Step_Test' => '5. Aşağıdaki "Test etiketi yazdır" düğmesine tıklayın. QZ Tray izin isterse Allow\'a tıklayın — sertifika kuruluysa bir daha sormaz.',
'QZ_Step_Save' => '6. Bu ayarları kaydetmek için Gönder\'e tıklayın. Barkod Yazdır sayfasındaki etiketler artık tarayıcı yazdırma penceresi olmadan doğrudan bu yazıcıda yazdırılacak.',
'QZ_Setup_Note' => 'QZ Tray, siteye eriştiğiniz bilgisayarda çalışır; bu nedenle Stocky uzak bir sunucuda barındırılsa bile çalışır. Etiket yazdıran her bilgisayarda QZ Tray kurulu olmalıdır.',

