'Ord_Guide_Payment_Title' => 'Ödeme durumu',
'Ord_Guide_Payment_Intro' => 'Bu sütun, müşterinin ödeme sırasında nasıl ödemeyi seçtiğini kaydeder. Mağaza tarafından belirlenir ve bu sayfadan düzenlenemez — paranın kendisi, siparişi onaylamanın oluşturduğu satışta izlenir.',
