'Ord_Guide_Payment_Pending' => 'Kapıda ödeme, banka havalesi veya başka bir sonradan ödeme yöntemi. Siparişi onaylamak satışı Ödenmedi olarak oluşturur; parayı tahsil ettiğinizde kendiniz kaydedersiniz — aşağıdaki adımlara bakın.',
'Ord_Guide_Payment_Failed' => 'Ağ geçidi ödemeyi reddetti veya müşteri ödemeden vazgeçti. Sipariş otomatik olarak iptal edilir.',
'Ord_Guide_MarkPaid_Title' => 'Ödeme durumunu Bekliyor\'dan Ödendi\'ye çevirme',
'Ord_Guide_MarkPaid_Step1' => 'Önce siparişi burada onaylayın — satışı oluşturan onaylamadır.',
'Ord_Guide_MarkPaid_Step2' => 'Satışlar > Tüm Satışlar\'ı açın ve o satışı bulun (aynı müşteri; ayrıntı sayfası hangi çevrimiçi siparişten geldiğini gösterir).',
'Ord_Guide_MarkPaid_Step3' => 'Satır işlemleri menüsünü açın ve Ödeme Oluştur\'u seçin.',
'Ord_Guide_MarkPaid_Step4' => 'Tutarı, ödeme yöntemini ve tarihi girip kaydedin. Satış, tutara bağlı olarak kendiliğinden Kısmi veya Ödendi durumuna geçer.',
'Ord_Guide_MarkPaid_Note' => 'Burada gösterilen Ödeme Durumu, ödeme sırasındaki seçimi kaydetmeye devam eder ve olduğu gibi kalır. Satış, muhasebe kaydıdır ve ödeme ile kâr raporlarınızı besleyen odur. Girdiklerinizi incelemek veya düzenlemek için satışta Ödemeleri Göster\'i kullanın.',
'Ord_Guide_Notes_Title' => 'Bilinmesi gerekenler',
'Ord_Guide_Note_Warehouse' => 'Onaylarken seçtiğiniz depo, stokun nereden alınacağını belirler. Tüm siparişi karşılayamayan depolar o listede Stokta Yok olarak işaretlenir.',
'Ord_Guide_Note_Preorder' => 'Ön sipariş ürünleri stok kontrolünü atlar; bu yüzden bunları içeren bir sipariş, miktar henüz elde olmasa bile onaylanabilir.',
'Ord_Guide_Note_Flagged' => 'İşaretlendi etiketi, siparişin ödeme sırasında bir dolandırıcılık kontrolüne takıldığı anlamına gelir. Nedenini görmek için etiketin üzerine gelin ve onaylamadan önce siparişi inceleyin.',
