'VG_Intro' => 'Değişken bir ürün birkaç varyant olarak satılır. Bunları seçeneklerden (önerilen) veya basit bir ad listesi olarak oluşturun. Her varyantın kendi kodu, fiyatları, görseli ve stoğu vardır.',
