'VG_Opt_Step3' => 'Bir değer yazın (örneğin Kırmızı) ve Enter\'a basın. Her değer için tekrarlayın; virgül de değerleri ayırır. Bir değeri kaldırmak için üzerindeki x işaretine tıklayın.',
