'VG_Opt_Step8' => 'İsteğe bağlı: bir seçenekte "Renk örnekleri"ni işaretleyin ve her değer için bir renk seçin; mağaza bunu renkli bir nokta olarak gösterir.',
'VG_Rows_Title' => 'Varyant satırları',
'VG_Rows_Text' => 'Her satırda görsel, kod, barkod, maliyet, fiyat, toptan fiyat ve minimum satış fiyatı bulunur. Ürün oluştururken her varyant için depo başına açılış stoğunu da girebilirsiniz. "Eksik" etiketi, satırda bir seçenek için değer bulunmadığı anlamına gelir.',
'VG_List_Title' => 'Basit liste modu',
