'Upd_Guide_Phase_Database' => '{label} — migration\'lar çalıştırılır, ardından izinler, çeviriler ve şablonlar yenilenir.',
'Upd_Guide_Phase_Cache' => '{label} — tüm önbellekler temizlenir ve yeniden oluşturulur.',
'Upd_Guide_Phase_Verify' => '{label} — sağlık kontrolleri yeni sürümün açıldığını, veritabanının çalıştığını, tüm migration\'ların çalıştırıldığını ve yapılandırmanın geçerli olduğunu doğrular.',
'Upd_Guide_Phase_Done' => '{label} — bakım modu kaldırılır ve geçici dosyalar temizlenir.',
'Upd_Guide_Run_Success' => '{success} mesajını gördüğünüzde {reload} düğmesine tıklayın ve yeni yönetim paneli dosyalarının yüklenmesi için tarayıcınızı zorla yenileyin ({keys}).',
'Upd_Update_Successful_Short' => 'Güncelleme başarılı',
'Upd_Guide_No_Internet' => 'Güncelleme sırasında internet bağlantısına gerek yoktur — her şey yüklenen ZIP dosyasından gelir. Bağlantınızın kopması veya tarayıcıyı kapatmanız güncellemeyi BOZMAZ: sunucu tam olarak nerede durduğunu hatırlar.',
'Upd_Guide_Wrong_Title' => '3. Bir şeyler ters giderse',
'Upd_Guide_Wrong_Rollback' => '{label} — dosyalar değişmeye başladıktan sonra herhangi bir şey başarısız olursa (çıkarma hatası, migration hatası, başarısız sağlık kontrolü, disk dolu, …), sistem önceki dosyaları ve veritabanını doğrulanmış yedekten otomatik olarak geri yükler, bakım modunu kaldırır ve {message} mesajını bildirir. Tam olarak başladığınız noktaya dönersiniz.',
'Upd_Automatic_Rollback' => 'Otomatik geri alma',
'Upd_Failed_Previous_Restored' => 'Güncelleme başarısız — önceki sürüm geri yüklendi',
'Upd_Guide_Wrong_Interrupted' => '{label} (sunucunun yeniden başlatılması, zaman aşımı, kapatılan tarayıcı, elektrik kesintisi) — bu sayfayı yeniden açtığınızda kırmızı bir bant iki güvenli seçenek sunar: {resume} (tam olarak durduğu adımdan devam eder) veya {rollback} (önceki sürümü yedekten geri yükler).',
'Upd_Interrupted_Update' => 'Yarıda kesilen güncelleme',
'Upd_Guide_Wrong_Unreachable' => '{label} — {path} adresindeki bağımsız {console} aracını kullanın. Site bakım modundayken veya yönetim paneli dosyaları bozuk olsa bile çalışır ve aynı Devam Et / Geri Al işlemlerini sunar. Ayrıca bakım ekranının altında gizli bir "Yönetici erişimi" bağlantısı bulunur.',
'Upd_Admin_Unreachable' => 'Yönetim paneline erişilemiyor',
'Upd_Recovery_Console' => 'kurtarma konsolu',
'Upd_Guide_Wrong_Locked_Out' => '{label} — bir güncelleme çalışırken bu sayfada bir {link} gösterilir. Tekrar girmeniz gerekirse (örneğin oturumunuzun süresi dolduktan sonra) bunu kaydedin; bakım ekranını aşmanızı ve yeniden oturum açmanızı sağlar.',
'Upd_Locked_Out_Maintenance' => 'Bakım modu nedeniyle erişim engellendi',
'Upd_Bypass_Link' => 'atlama bağlantısı',
'Upd_Guide_Wrong_Concurrent' => '{label} — şu mesajı görürler: {message} Aynı anda yalnızca bir güncelleme çalışabilir.',
'Upd_Another_Admin_Updating' => 'Başka bir yönetici aynı anda güncelleme yapmaya çalışırsa',
'Upd_Guide_Backups_Title' => '4. Yedekler ve geri yükleme',
'Upd_Guide_Backups_Created' => 'Her güncelleme, herhangi bir şeye dokunmadan {before} bir yedek oluşturur: güncellemenin değiştirebileceği tüm uygulama dosyaları, {env} dosyasının bir kopyası ve tam bir veritabanı dökümü. Yüklemeler ve {storage} bir güncelleme tarafından asla değiştirilmez ve bu nedenle yedeğe dahil edilmez — bunların yedeklerini kendiniz alın. Yedekler {path} konumunda saklanır ve web üzerinden asla erişilemez.',
'Upd_Before' => 'önce',
'Upd_Guide_Backups_Panel' => '{tab} sekmesindeki {panel} paneli bunları tarih, sürüm ve boyutla listeler. Buradan herhangi bir tam yedeği {restore} (dosyalar + veritabanı — önce mevcut veritabanının bir güvenlik kopyası alınır) ya da eski yedekleri {delete}.',
'Upd_Restore_Verb' => 'geri yükleyebilir',
'Upd_Delete_Verb' => 'silebilirsiniz',
'Upd_Guide_Backups_Retention' => 'Kaç yedeğin saklanacağını seçmek için {keep} ayarını kullanın; eski yedekler her başarılı güncellemeden sonra otomatik olarak kaldırılır. Kalan tek tam yedek asla silinemez — her zaman bir geri dönüş yolunuz olur.',
'Upd_Guide_Manual_Title' => '5. Manuel güncelleme (yedek yöntem)',
'Upd_Guide_Manual_Text' => 'Elle güncellemeyi tercih ediyorsanız veya yükleyici sunucunuzda kullanılamıyorsa, bu sayfanın {tab} sekmesindeki adım adım talimatları izleyin.',
'Upd_Guide_Clear_Cache_First' => 'Herhangi bir güncellemeden sonra sayfalar bozuk veya boş görünüyorsa önce tarayıcı önbelleğinizi temizleyin — neredeyse her zaman sebep budur.',
'Upd_Restore_Backup_Confirm' => 'Bu yedek geri yüklensin mi? Mevcut dosyalar ve mevcut veritabanı yedekle değiştirilecektir. Önce mevcut veritabanının bir güvenlik kopyası alınır. (v{version} — {date})',
'Woo_Guide_Lead' => 'Bir WooCommerce mağazasının ERP ile nasıl senkron kaldığı. Aşağıdaki cron satırları bu sunucu için oluşturulmuştur, bu yüzden doğrudan kopyalanabilir.',
'Woo_Guide_Ways_Note' => 'Shopify\'ın aksine WooCommerce, ERP\'ye kendiliğinden hiçbir şey göndermez — burada webhook alıcısı yoktur, bu yüzden {in} gelen her şey zamanlanmış olarak ulaşır. Yalnızca {out} giden stok anında olabilir.',
'Woo_In' => 'içeri',
'Woo_Out' => 'dışarı',
'Woo_Guide_Both_Ways_Title' => 'Her iki yön için önce bu gerekir',
'Woo_Api_Keys' => 'API Anahtarları',
'Woo_Guide_Api_Keys_Text' => '{path}, izin {perm}. Tüketici anahtarını ve gizli anahtarı mağaza URL\'siyle birlikte {settings} sekmesine kopyalayın — sitenizin sonunda eğik çizgi olmayan adresi, ör. {example}.',
'Woo_Credentials_Saved' => 'kimlik bilgileri kaydedildi',
'Woo_Not_Configured_Yet' => 'henüz yapılandırılmadı',
'Woo_Guide_Wp_App_Password_Title' => 'WordPress uygulama parolası (isteğe bağlı)',
'Woo_Guide_Wp_App_Password_Text' => 'Yalnızca ürün görselleri için kullanılır. WooCommerce API\'si ürünleri, stoku, kategorileri, markaları, müşterileri ve siparişleri taşır; Medya Kitaplığı\'nda arama yapan ve henüz orada olmayan bir görseli yükleyen ise WordPress API\'sidir.',
'Woo_Guide_Wp_App_Password_Note' => 'Medyayı yönetebilen bir WordPress kullanıcısı kullanın ve parolayı {path} altında oluşturun. Her iki alanı da boş bırakırsanız her şey yine senkronize olur — yalnızca görsel ekleme atlanır.',
'Woo_Guide_Pick_Way_Title' => 'Ardından nasıl senkron kalacağını seçin',
'Woo_Right_Away' => 'Hemen',
'Woo_Stock_Live' => 'stok canlı',
'Woo_Stock_Not_Live' => 'stok canlı değil',
'Woo_Guide_Realtime_Lead' => 'Yalnızca tek yön: ERP\'den çıkan stok ve ürünler. WooCommerce\'te yapılan siparişler ve ürün düzenlemeleri yine zamanlamaya göre gelir — diğer sekmeye bakın.',
'Woo_Push_Stock_On_Change' => 'Stok değiştiği anda gönder',
'Woo_Setting_People_Miss' => 'Bu, insanların gözden kaçırdığı ayardır',
'Woo_Guide_Pos_Sale_Not_Reach' => 'Bir POS satışı WooCommerce\'e kendiliğinden {not}. Kapalı bırakılırsa mağaza bunu ancak bir sonraki stok senkronizasyonunda — varsayılan olarak bir saat sonra — öğrenir ve bu aralıkta kasada zaten sattığınız bir ürünü satabilir.',
'Woo_Does_Not' => 'ulaşmaz',
'Woo_Guide_Tick_Instant' => '{settings} sekmesinde {option} seçeneğini işaretleyin. Kurulumun tamamı budur — çalışan yok, cron yok. Her satış, iade, stok düzeltme, transfer ve teslim alınan satın alma, satış kaydedildikten hemen sonra yalnızca ilgili ürünler için bir gönderim yapar ve yirmi satırlık bir satış yirmi değil tek bir gönderime mal olur. Kasa bunu asla beklemez.',
'Woo_Currently' => 'Şu anda:',
'Woo_Instant_On_Text' => 'açık — stok değiştiğinde gönderilir',
'Woo_Instant_Off_Text' => 'kapalı — stok yalnızca zamanlamaya göre',
'Woo_Guide_Instant_Note' => 'Yalnızca WooCommerce\'e zaten bağlı ürünler gönderilir — hiç senkronize edilmemiş bir ürünün mağazada düzeltilecek bir karşılığı yoktur. Varyantlı ürünler üst ürünleri üzerinden gider ve bir kombo, bileşenlerinden herhangi biri hareket ettiğinde yeniden gönderilir. Toplu işlemler (ürün silme, depo sıfırlama) olay tetiklemeden stok yazar; bu da saatlik stok senkronizasyonunu korumanın bir nedenidir.',
'Woo_Push_Products_On_Save' => 'Ürünleri kaydedildikleri anda gönder',
'Woo_Guide_Tick_Auto_Products' => '{settings} sekmesinde {option} seçeneğini işaretlediğinizde Stocky\'de oluşturulan, düzenlenen veya kopyalanan bir ürün kaydedildikten hemen sonra WooCommerce\'e gönderilir — ayrıntılar, fiyat, varyantlar ve görseller, ardından stoku. Yeni bir ürün, gece çalışan ürün senkronizasyonunu beklemek yerine mağazada hemen oluşturulur.',
'Woo_On' => 'açık',
'Woo_Off' => 'kapalı',
'Woo_Guide_Bulk_Imports_Note' => 'Toplu içe aktarmalar tek tek gönderilmez — bir içe aktarmadan sonra ürün senkronizasyonu çalıştırın. Gönderilen bir ürünün doğru kategoriye düşmesi için önce kategorileri ve markaları senkronize edin.',
'Woo_Nothing_Else_To_Install' => 'Yüklenecek başka bir şey yok',
'Woo_Guide_Same_Process' => 'Kuyruk çalışanı yok, cron girdisi yok. Gönderim, satışı sunan aynı süreçte, yanıt geri gönderildikten {after} çalışır; böylece kasa asla WooCommerce\'i beklemez. Gönderimler asla çakışmaz: biri çalışırken yapılan değişiklikler onu bekler ve hemen ardından gönderilir.',
'Woo_After' => 'sonra',
'Woo_Guide_Shop_Stops_Answering' => 'Yanıt vermeyi bırakan bir mağazadan sekiz saniye sonra vazgeçilir ve her satışın onu yeniden beklememesi için gönderimler beş dakika duraklatılır; bu sürede gelen değişiklikler duraklamadan sonraki ilk gönderimle gider ve saatlik stok senkronizasyonu her durumda eksikleri tamamlar. Her duraklama Günlükler sekmesine kaydedilir.',
'Woo_Guide_Artisan_Exception' => 'Bir istisna: artisan komutuyla yapılan bir stok değişikliğinin ardından gelebileceği bir yanıt yoktur, bu nedenle bunun yerine {queue} kuyruğuna alınır. Bunların da hızla gönderilmesi için bu kuyruğu boşaltın:',
'Woo_Cron_Line_Copied' => 'Cron satırı kopyalandı',
'Woo_Command_Copied' => 'Komut kopyalandı',
'Woo_Guide_Not_Woo_Queue' => 'Bilinçli olarak {queue} kuyruğu değil: o kuyruk saatler süren katalog gruplarını taşır ve onların arkasında kuyruğa alınan anlık bir gönderim anlık olmazdı.',
'Woo_On_A_Schedule' => 'Zamanlanmış',
'Woo_Guide_Scheduled_Lead' => 'Her şey belirli aralıklarla her iki yönde yeniden kontrol edilir. Siparişler ERP\'ye bu şekilde ulaşır, katalog bu şekilde yayımlanır ve hızlı yolun kaçırdığı her şey bu şekilde onarılır. Her işin kendi cron girdisi vardır, böylece yalnızca istediklerinizi çalıştırırsınız.',
'Woo_Guide_Sync_Drains_Queue' => '{command} çalışırken kendi kuyruğunu boşaltır, bu nedenle bu satırlar ayrı bir çalışana ihtiyaç duymaz. Windows\'ta, {path} konumunda başlatılan, program {program} ve aynı bağımsız değişkenlerle Görev Zamanlayıcı\'yı kullanın.',
'Woo_Or_No_Cron' => 'Ya da hiç cron olmadan',
'Woo_Guide_No_Cron_Text' => 'Buradaki her sekme isteğe bağlı olarak senkronize eder ve manuel bir senkronizasyon sayfa açıkken kendi gruplarını boşaltır — bu nedenle küçük bir mağaza hiç cron girdisi olmadan çalışabilir. Kaybettiğiniz şey, kimse bakmazken olan her şeydir: siparişler yalnızca biri düğmeye bastığında gelir.',
'Woo_Commands_Worth_Knowing' => 'Bilinmesi gereken komutlar',
'Woo_Worth_Knowing' => 'Bilinmesi gerekenler',
'Woo_Guide_Changing_Url_Clears' => 'Mağaza URL\'sini veya API anahtarlarını değiştirmek tüm eşlemeleri temizler — ürünler, kategoriler, markalar ve müşteriler yeni mağazaya yeniden senkronize edilir.',
'Woo_Guide_Keep_Skus' => 'SKU\'ları Stocky ile WooCommerce arasında tutarlı tutun: kopyaları önleyen ve yeniden bağlamayı güvenli kılan budur.',
