'Woo_No_Shop_Connected_Desc' => 'Aşağıdakilerin hepsi yine geçerlidir — WooCommerce ayarları sayfasında mağaza URL\'sini ve API anahtarlarını girin, ardından geri dönün.',
'Woo_Wp_Username' => 'WordPress kullanıcı adı',
'Woo_Wp_App_Password' => 'WordPress uygulama parolası',
'Woo_Settings_Instant_Hint' => 'Bir satış, iade veya stok düzeltme, kaydedildiği anda yalnızca ilgili ürünler için bir stok gönderimi yapar; böylece mağaza bir sonraki saatlik stok senkronizasyonunu beklemeden saniyeler içinde güncel olur. Yüklenecek başka bir şey yok — gönderim, satış yanıtlandıktan sonra çalışır, bu yüzden kasa asla WooCommerce\'i beklemez. Daha fazlası {guide} sekmesinde.',
'Woo_Settings_Instant_Off_Alert' => 'Kapalı bırakırsanız bir POS satışı WooCommerce\'e yalnızca bir sonraki stok senkronizasyonunda — bir saate kadar sonra — ulaşır.',
'Woo_Settings_Auto_Products_Hint' => 'Stocky\'de oluşturulan, düzenlenen veya kopyalanan bir ürün, ürün senkronizasyonunu beklemek yerine kaydedildikten hemen sonra WooCommerce\'e gönderilir — ayrıntılar, fiyat, varyantlar, görseller, ardından stoku. Toplu içe aktarmalar gönderilmez; bir içe aktarmadan sonra ürün senkronizasyonu çalıştırın.',
'Woo_Sync_Tuning' => 'Senkronizasyon İnce Ayarı',
'Woo_Sync_Tuning_Intro' => 'Varsayılanlar çoğu mağazaya uygundur. Bunları yalnızca senkronizasyon yavaşsa veya barındırmanızda zaman aşımına uğruyorsa değiştirin. Her değer güvenli bir aralıkla sınırlandırılır ve bir alanı temizlemek varsayılanını geri yükler.',
'Woo_Setting_This_Up' => 'Kurulum',
'Woo_Setting_This_Up_Text' => 'API anahtarlarını edinme, WordPress uygulama parolasının ne işe yaradığı, zamanlanmış senkronizasyonlar için cron girdileri ve stokun değiştiği anda mağazaya ulaşmasını sağlama — bunların hepsi, bu sunucunun kopyalanmaya hazır cron satırlarıyla birlikte Rehber sekmesindedir. Tek bir kopya, böylece modülün gerçekte yaptığından sapamaz.',
