'Shopify_Stock_Lag_Desc' => 'O zamana kadar tezgâhtaki bir satış mağazada görünmez — {n} dakikaya kadar; bu nedenle son ürün çevrimiçi olarak yine de iki kez satılabilir. {setting} seçeneğini açın; her satış, iade ve stok düzeltmesi bunun yerine saniyeler içinde gönderilsin.',
'Shopify_Turn_It_On' => 'Aç',
'Shopify_Stock_Also_Pushed' => 'Stok, yukarıdaki bir adımı beklemeden, herhangi bir satış, iade veya stok düzeltmesinden sonraki saniyeler içinde de gönderilir.',
