'Shopify_Hook_Msg_Token' => 'Aşağıdaki “Webhook\'ları kaydet” düğmesine tıklayın ve uygulamanın API gizli anahtarını mağaza ayarlarına imzalama anahtarı olarak yapıştırın.',
'Shopify_Hook_Note_Register' => 'Kayıt işlemi, abonelikleri Shopify\'da oluşturur ve otomatik olarak bu adrese yönlendirir. Shopify → Ayarlar → Bildirimler → Webhook\'lar altında elle eklemeyin: bunlar farklı bir anahtarla imzalanır ve her teslimat reddedilir.',
'Shopify_Hook_Verified_Client' => 'Teslimatlar, zaten kayıtlı olan uygulamanın istemci gizli anahtarıyla doğrulanır.',
'Shopify_Hook_Signature_Required' => 'Geçerli imzası olmayan teslimatlar reddedilir, bu nedenle webhook\'ların işe yaraması için önce gizli anahtarın ayarlanması gerekir.',
'Shopify_Hook_Retries' => 'Shopify bir 2xx yanıtı alana kadar yeniden dener ve her teslimat bir kez kaydedilir — tekrarlanan bir olay hiçbir şey yapmaz, yinelenen bir sipariş oluşturmaz.',
