'Shopify_G_Lead_Store' => 'Bu mağazanın güncel kalabilmesi için ihtiyaç duydukları. Buradaki her şey bu mağazaya özeldir — yollar ve kimlikler gerçektir, bu nedenle komutlar doğrudan sunucuya kopyalanabilir.',
'Shopify_G_Lead_Generic' => 'Bir Shopify mağazasının ERP ile nasıl uyumlu kaldığı. Kendi durumunu görmek için yukarıdan bir mağaza seçin veya olduğu gibi okuyun — hangi mağazayı bağlarsanız bağlayın cron satırı ve webhook URL\'si aynıdır.',
'Shopify_G_Ways_Note' => 'Çoğu mağaza ikisini birden kullanır: ilki mağazayı dakika dakika güncel tutar, ikincisi ilkinin kaçırdığı her şeyi yakalar — hiç ulaşmayan bir webhook, doğrudan Shopify yönetici panelinde yapılan bir düzenleme, sitenin kapalı olduğu bir gece.',
'Shopify_G_Both_Need' => 'Her iki yöntem için önce bu gerekir',
'Shopify_G_Credentials' => 'Shopify kimlik bilgileri',
'Shopify_G_Cred_Intro' => 'Ocak 2026\'dan itibaren Shopify yönetici panelinde artık özel uygulama oluşturmamaktadır, bu nedenle iki tür bağlantı vardır:',
'Shopify_G_Cred_DevDash' => '{app} (şu anda bağlanan her mağaza) — {path}. Bu mağazanın eşitlediği veriler için Admin API kapsamlarını verin, uygulamayı mağazaya yükleyin, ardından uygulamanın Ayarlar sayfasındaki {clientId} ve {clientSecret} değerlerini {where} alanına kopyalayın. ERP bunları kendisi bir erişim belirteciyle değiştirir ve her 24 saatte bir süresi dolmadan önce yeniler. İstemci gizli anahtarı webhook\'ları da imzalar, bu nedenle başka bir şeye gerek yoktur. Uygulama ve mağaza aynı Shopify organizasyonunda olmalıdır.',
'Shopify_G_Dev_Dashboard_App' => 'Dev Dashboard uygulaması',
'Shopify_G_Cred_Legacy' => '{app} (2026\'dan önce yönetici panelinde oluşturulmuş) — {token} ({prefix}) ile ve webhook imzalama anahtarı olarak {secret} ile değişmeden çalışmaya devam eder. Bu, belirteçle aynı değer değildir; ikisini karıştırmak, webhook\'ların reddedilmesinin olağan nedenidir.',
'Shopify_G_Legacy_App' => 'Eski özel uygulama',
'Shopify_G_API_Secret_Key' => 'API gizli anahtarı',
'Shopify_G_Stored' => 'kayıtlı',
'Shopify_G_Missing_Refused' => 'eksik — teslimatlar reddedilecek',
'Shopify_G_Where_Data_Desc' => '{path} Bu mağazanın stokunu sattığı ERP deposu ve bu stokun yazıldığı Shopify konumu. Envanter eşitlemesi ve sipariş içe aktarma bunlar olmadan çalışmaz.',
'Shopify_G_Currently' => 'Şu anda: depo {warehouse}, konum {location}',
'Shopify_G_Not_Set_Lower' => 'ayarlanmadı',
'Shopify_G_Ready' => 'hazır',
'Shopify_G_Incomplete' => 'eksik',
'Shopify_G_Manual_Syncs' => 'Elle başlattığınız eşitlemeler',
'Shopify_G_Manual_Desc' => '{centre} üzerinden başlatılan bir eşitleme hemen yanıt verir ve arka planda, her biri bir öncekinin kaldığı yerden devam eden kısa dilimler halinde çalışır. Büyük bir katalog, uzun web isteklerini sonlandıran barındırma ortamları (LiteSpeed, nginx, yük dengeleyici) tarafından yarıda kesilmez ve sayfayı kapatmak işlemi durdurmaz. Bunun için çalışan, bir cron satırı daha gerektirir:',
'Shopify_G_Cron_Copied' => 'Cron satırı kopyalandı',
'Shopify_G_Manual_Note' => 'Bu olmadan da eşitleme tamamlanır, ancak yalnızca Eşitleme Merkezi sayfası açık kaldığı sürece: birkaç saniye içinde hiçbir çalışan bir çalıştırmayı üstlenmezse sayfa işlemi her seferinde kısa bir istekle kendisi sürdürür. Windows\'ta Görev Zamanlayıcı\'yı her dakika kullanın: program {program}, bağımsız değişkenler {args}, başlangıç dizini {dir}.',
'Shopify_G_Then_Pick' => 'Ardından nasıl güncel kalacağını seçin',
'Shopify_G_Right_Away' => 'Anında',
'Shopify_G_Stock_Live' => 'stok canlı',
'Shopify_G_Stock_Not_Live' => 'stok canlı değil',
'Shopify_G_Realtime_Lead' => 'Her değişiklik gerçekleştiği anda, saniyeler içinde gönderilir. İki yarısı vardır ve bunlar ayrı anahtarlardır: {webhooks} mağazanın kendi olaylarını içeri alır, {push} ise stoku dışarı gönderir.',
'Shopify_G_Webhooks_Lower' => 'webhook\'lar',
'Shopify_G_Instant_Push_Lower' => 'anlık stok gönderimi',
'Shopify_G_Webhooks_In' => 'Webhook\'lar — mağaza → ERP',
'Shopify_G_Webhooks_Desc' => 'Shopify\'da yapılan siparişler, sipariş durumu değişiklikleri ve ürün, müşteri ve stok düzenlemeleri. Mağazayı açın ve {tab} içindeki {button} düğmesine basın — iki kez basmak güvenlidir. Shopify şu adrese gönderir:',
'Shopify_G_Webhooks_Tab' => 'Webhook\'lar sekmesi',
'Shopify_G_Webhooks_Note' => 'Adres internetten HTTPS üzerinden erişilebilir olmalıdır — Shopify, {localhost} veya bir {test} alan adına teslimat yapmaz. Her teslimat bir kez kaydedilir, bu nedenle Shopify\'ın yeniden denemeleri yinelenen sipariş oluşturamaz ve başarısız olanlar yeniden oynatılabilir. 1. adımdaki imzalama anahtarı kaydedilene kadar teslimatlar reddedilir.',
'Shopify_G_Instant_Out' => 'Anlık stok gönderimi — ERP → mağaza',
'Shopify_G_Setting_Missed' => 'İnsanların gözden kaçırdığı ayar budur',
'Shopify_G_Pos_Not_Auto' => 'Bir POS satışının Shopify\'a kendiliğinden ulaşması söz konusu {not}. Kapalı bırakılırsa mağaza bunu yalnızca bir sonraki Envanter gönderme adımında öğrenir — ve bu aralıkta kasada zaten sattığınız bir ürünü satabilir.',
'Shopify_G_Not' => 'değil',
'Shopify_G_Tick_Push' => '{where} üzerinde {setting} seçeneğini işaretleyin. Kurulumun tamamı budur — çalışan yok, cron yok. Bundan sonra her satış, iade ve stok düzeltmesi, satış kaydedildikten hemen sonra yalnızca ilgili ürünler için bir gönderim yapar ve yirmi satırlık bir satış yirmi değil, tek bir gönderime mal olur. Kasa bunu hiçbir zaman beklemez.',
'Shopify_G_This_Store' => 'Bu mağaza:',
'Shopify_G_Push_On' => 'açık — stok değişiklikte gönderilir',
'Shopify_G_Push_Off' => 'kapalı — stok yalnızca zamanlamaya göre',
'Shopify_G_Push_Note' => 'Yalnızca zaten bir Shopify eşlemesi olan ürünler ve yalnızca bu mağazanın deposundaki hareketler gönderilir. Toplu işlemler — bir ürünü silmek, bir depoyu sıfırlamak — bir olay tetiklemeden stok yazar; bu da zamanlanmış envanter adımını da korumak için bir nedendir.',
'Shopify_G_Nothing_Install' => 'Kurulacak başka bir şey yok',
'Shopify_G_No_Worker_Note' => 'Her iki yarı da kuyruk çalışanı veya cron girdisi gerektirmez. Gelen bir webhook, Shopify\'ın yaptığı istek içinde işlenir; giden bir stok gönderimi, satışı sunan aynı süreçte, yanıt geri gönderildikten {after} çalışır — böylece kasa hiçbir zaman Shopify\'ı beklemez ve yanıt vermeyi bırakan bir mağazadan on saniye sonra vazgeçilerek bir sonraki zamanlanmış envanter gönderimine bırakılır.',
'Shopify_G_After' => 'sonra',
'Shopify_G_Artisan_Note' => 'Bir istisna: artisan komutuyla yapılan bir stok değişikliğinin ardından gelebileceği bir yanıt yoktur, bu nedenle bunun yerine {queue} kuyruğuna alınır. Bunların da hızla gönderilmesini istiyorsanız o kuyruğu işleyin:',
'Shopify_G_On_Schedule' => 'Zamanlamaya göre',
'Shopify_G_On_Lower' => 'açık',
'Shopify_G_Off_Lower' => 'kapalı',
'Shopify_G_Scheduled_Lead' => 'Her şey belirli aralıklarla, her iki yönde yeniden kontrol edilir. Gerçek zamandan daha yavaştır, ancak anlık gönderim kullanmayan mağazalarda stoku dışarı gönderen, kaçırılan bir webhook\'u yakalayan ve bütün bir kataloğu aktarmanın tek yolu budur.',
'Shopify_G_Cron_Entry' => 'Cron girdisi',
'Shopify_G_Cron_Entry_Desc' => 'Bu olmadan zamanlanmış hiçbir şey çalışmaz. Tek bir satır, yalnızca bu modül için — zamanlamayı seçtiğiniz diğer işlerin yanına ekleyin:',
'Shopify_G_Cron_Note' => 'Bir planın kullanabileceği en ince çözünürlük beş dakikadır, çünkü en kısa adım aralığı beş dakikadır. Daha seyrek bir girdi ise alt sınır olur — {example} ile 5 dakikaya ayarlanmış bir adım her 15 dakikada bir çalışır. Windows\'ta Görev Zamanlayıcı\'yı kullanın: program {program}, bağımsız değişkenler {args}, başlangıç dizini {dir}.',
'Shopify_G_Switch_On_Plan' => 'Açın ve planı seçin',
'Shopify_G_Plan_Desc' => '{where} Anahtar, cron\'un herhangi bir işlem yapıp yapamayacağını belirler; plan ise ne yapacağını belirler. Bir {step}, kendi aralığına sahip, tek yönde tek bir varlıktır — {first}, {second}. Varsayılan aralık, kendi kutusunu boş bırakan her adım tarafından kullanılır.',
'Shopify_G_Step_Lower' => 'adım',
'Shopify_G_Plan_Note' => 'Planı boş bırakırsanız mağaza, varsayılan aralıkta siparişleri çeker ve stoku gönderir; çoğu mağazanın istediği de budur. Siparişler yalnızca çekilir: müşterinin sipariş verdiği yer Shopify\'dır.',
'Shopify_G_Schedule_On' => 'zamanlama açık',
'Shopify_G_Schedule_Off' => 'zamanlama kapalı — yalnızca elle',
'Shopify_G_When_Step_Runs' => 'Bir adım gerçekte ne zaman çalışır',
'Shopify_G_When_Note' => 'Bir adımın zamanı, aynı adımın en son {started} zamandan bu yana aralığından daha uzun süre geçtiğinde gelir; bu bilgi çalıştırma geçmişinden okunur. Bu nedenle elle başlattığınız bir eşitleme bir sonraki otomatik eşitlemeyi erteler ve sürekli başarısız olan bir adım her tetiklemede değil, kendi aralığında yeniden denenir. Mağazanın Genel Bakış sayfası her adımın son çalıştırmasını, bir sonraki zamanını ve engellendiğinde nedenini gösterir. İlk katalog gönderimini zamanlamaya almadan önce elle çalıştırın — önce {dryRun} ile.',
'Shopify_G_Started_Lower' => 'başlatıldığı',
'Shopify_G_Where_Setting' => 'Her ayarın bulunduğu yer',
'Shopify_G_Where_Setting_Note' => 'Bunların tümü mevcut bir mağazadadır: {path}, ardından kalem simgesi (veya mağazanın kendi sayfasında {edit}).',
'Shopify_G_Product_Images' => 'Ürün görselleri',
'Shopify_G_Img_1' => 'Görseller, {push} sırasında ürünle birlikte gönderilir — önce ana görsel, sonra galeri, ardından kendi görseli olan her varyant için bir tane, en fazla elli adet.',
'Shopify_G_Products_Push' => 'ürün gönderimi',
'Shopify_G_Img_2' => 'Bir varyantın görseli ürünle birlikte yüklenir ve ardından {assigned}; Shopify bunu böyle modeller: bir varyant, ürünün görsellerinden birini işaret eder. Ana görseli yeniden kullanan bir varyant onu iki kez yüklemez.',
'Shopify_G_Assigned' => 'o varyanta atanır',
'Shopify_G_Img_3' => 'Dosya olarak saklanan bir görsel Shopify\'a bağlantı olarak verilmez, {uploaded}; bu nedenle bu kurulum internetten erişilebilir olmasa bile çalışır. Yapıştırılmış bir bağlantı olarak eklenen görsel ise Shopify\'a o URL olarak iletilir ve herkese açık şekilde erişilebilir olmalıdır.',
'Shopify_G_Uploaded' => 'doğrudan yüklenir',
'Shopify_G_Img_4' => 'Yalnızca gerçekten değiştiklerinde yeniden gönderilirler — yalnızca fiyatı değiştiren bir gönderim mağazanın görsellerine dokunmaz, çünkü görselleri göndermek tüm seti değiştirir.',
'Shopify_G_Img_5' => 'ERP\'de bir görseli kaldırmak, onu Shopify\'da silmek demek {not}. Orada da silin, aksi halde mağaza onu göstermeye devam eder.',
'Shopify_G_Commands' => 'Bilinmesi gereken komutlar',
'Shopify_G_Command_Copied' => 'Komut kopyalandı',
'Shopify_G_Foot' => 'Her eşitleme {logs} bölümüne yazar ve her mağazanın Genel Bakış sayfası her adımın en son ne zaman çalıştığını, bir sonraki zamanını ve bir şey engelliyorsa neyin engellediğini gösterir. Bir eşitleme beklediğiniz şeyi yapmadığında önce buraya bakın.',
'Shopify_G_Covers' => 'Kapsam',
'Shopify_G_Covers_Rt' => 'Shopify\'da yapılan siparişler ve düzenlemeler; ERP\'den çıkan stok (bir POS satışı, bir iade, bir stok düzeltmesi)',
