'Cr_Guide_T_Statuses' => 'Durumlar',
'Cr_Guide_Statuses_Note' => 'Durumlar yalnızca ileriye doğru ilerler, bu nedenle geç gelen bir güncelleme paketi asla geriye çekmez. Teslim edilmiş bir paket yine de iade ediliyor veya iade edildi olarak bildirilebilir.',
