'Cr_Guide_S_returning' => 'Size geri dönüyor.',
'Cr_Guide_S_returned' => 'Size geri döndü: İncelenecek iadeler\'de bekler veya otomatik olarak stoğa geri eklenir.',
'Cr_Guide_S_cancelled' => 'Gönderi iptal edildi.',
'Cr_Guide_T_Booking' => 'Siparişler için gönderi oluşturma',
'Cr_Guide_B_Booking' => 'Kargoya gönder, formu satıştan doldurur: alıcı, adres, COD olarak kalan borç tutarı ve ürünlerin ağırlığı. Kendi şehir listesi olan kargo firmaları bir seçici gösterir ve seçiminiz o şehir için hatırlanır. Toplayıcılar, DHL, FedEx, UPS ve Lalamove Fiyatları karşılaştır seçeneği sunar: bir fiyat seçin ve Gönderi oluştur onu satın alır. Satış listesinden birden fazla satış için aynı anda gönderi oluşturulabilir.',
'Cr_Guide_T_Cod' => 'Kapıda ödeme',
'Cr_Guide_B_Cod' => 'Bir COD paketi Tahsil edilmedi durumundan Kargo firması tahsil etti (teslimatta) durumuna, oradan da Size ödendi durumuna geçer. Ödemeleri bildiren kargo firmaları son adımı kendileri ilerletir; diğerleri için COD\'yi güncelle\'yi kullanın. Kargo Ayarları\'nda bir hesap seçiliyse ödeme, satışta bir ödeme olarak kaydedilir. Bir paket tamamlandığında kargo ücretleri gider olarak kaydedilebilir.',
'Cr_Guide_T_Returns' => 'İade edilen paketler',
'Cr_Guide_B_Returns' => 'Varsayılan olarak iade edilen bir paket Kargo Gönderileri\'nde İncelenecek iadeler altında bekler. Stoğa geri ekle, siparişin tamamı için satış iadesi oluşturur ve ürünleri stoğa geri ekler; Kapat ise hasarlı veya kayıp paketler için hiçbir şeyi geri eklemez. Bunun yerine Kargo Ayarları stoğa otomatik geri ekleme yapabilir.',
'Cr_Guide_T_Customers' => 'Müşteri mesajları ve takip sayfası',
'Cr_Guide_B_Customers' => 'Kargo Ayarları\'ndaki müşteri bildirimleri, işaretlediğiniz durumlarda her paket için bir kez, kendi metninizle SMS, e-posta veya WhatsApp gönderir. Çevrimiçi mağazanızdaki takip sayfası, müşterilerin bir paketi takip numarasıyla veya sipariş numarası ve telefonla takip etmesini sağlar. Sık sık paket iade eden müşteriler, gönderi oluşturduğunuzda bir iade riski rozeti alır.',
'Cr_Guide_T_Labels' => 'Etiketler',
'Cr_Guide_B_Labels' => 'Etiket yazdır, kargo firması bir etiket veriyorsa (PDF, bağlantı veya görsel) onun kendi etiketini, aksi takdirde takip barkodu ve tahsil edilecek tutarı içeren bir Stocky etiketini verir. Yazdırmak için bu sitede açılır pencerelere izin verin. DHL, FedEx ve UPS etiketlerini yalnızca bir kez, gönderi oluşturulurken verir ve Stocky yeniden yazdırmak için saklar.',
'Cr_Guide_T_Faq' => 'Sorun giderme',
'Cr_Guide_Q_Test' => 'Bağlantı testi başarısız oluyor',
'Cr_Guide_A_Test' => 'Test modu anahtarları Test moduyla, canlı anahtarlar Canlı ile kullanılır; bunlar farklıdır. Kesin nedeni görmek için Kargo kayıtları\'nı açın ve kargo firmasının yanıtını okuyun.',
'Cr_Guide_Q_City' => 'Kargo firması şehri veya adresi reddediyor',
'Cr_Guide_A_City' => 'Şehri gönderi formundaki kargo şehir listesinden seçin; kargo firmaları yalnızca kendi adlarını kabul eder. Posta adresleriyle çalışan kargo firmaları ayrıca eyalet/il, posta kodu ve iki harfli ülke kodu da ister.',
'Cr_Guide_Q_Webhook' => 'Durumlar kendiliğinden değişmiyor',
'Cr_Guide_A_Webhook' => 'Güncelleme gönderen kargo firmaları için webhook URL\'sinin kargo firmasında kayıtlı olduğunu kontrol edin: Kargo kayıtları alınan her güncellemeyi veya birinin neden reddedildiğini (örneğin yanlış gizli anahtar) gösterir. Diğer kargo firmaları Kargo Ayarları\'ndaki programa göre kontrol edilir ve Durumu şimdi kontrol et anında sorgular.',
'Cr_Guide_Q_Stuck' => 'Bir gönderide durum kontrolü hatası görünüyor',
'Cr_Guide_A_Stuck' => 'Kargo firması son kontrolleri reddetti; neden gönderide ve Kargo kayıtları\'nda yer alır. Tekrarlanan hatalardan sonra gönderi artık otomatik olarak kontrol edilmez: nedeni düzeltin, ardından Durumu şimdi kontrol et\'i kullanın.',
'Cr_Guide_Q_Label' => 'Etiket yazdırırken hiçbir şey açılmıyor',
'Cr_Guide_A_Label' => 'Tarayıcınız açılır pencereyi engelledi. Bu sitede açılır pencerelere izin verin ve tekrar deneyin.',
'Cr_Guide_Q_Cod' => 'Bir COD ödemesi satışa kaydedilmedi',
